(7204319, 1109056, 140305, '<td valign="top">This really appeals to me because it has such a beautiful soft quality yet loaded with texture.  Interesting dynamic between the two animals, makes me wonder what they are thinking. Great shot.</td>', 'This really appeals to me because it has such a beautiful soft quality yet loaded with texture.  Interesting dynamic between the two animals, makes me wonder what they are thinking. Great shot.', '2014-04-16 12:59:01.000000', NULL, 1),
(7204320, 1109272, 140305, '<td valign="top">So pretty!  She appears to be on high alert. Nicely captured.</td>', 'So pretty!  She appears to be on high alert. Nicely captured.', '2014-04-16 13:00:45.000000', NULL, 1),
(7204321, 1109133, 50641, '<td valign="top">yikes don''t mess with him</td>', 'yikes don''t mess with him', '2014-04-16 13:01:08.000000', NULL, 1),
(7204322, 1109433, 50641, '<td valign="top">movin on up...</td>', 'movin on up...', '2014-04-16 13:02:01.000000', NULL, 1),
(7204325, 1109122, 50641, '<td valign="top">yeah, danm it</td>', 'yeah, danm it', '2014-04-16 13:05:14.000000', NULL, 1),
(7204327, 1108946, 153814, '<td valign="top">Very nice, great detail.</td>', 'Very nice, great detail.', '2014-04-16 13:06:28.000000', NULL, 1),
(7204331, 1109068, 140305, '<td valign="top">Seems a bit OOF to me. I think it would have benefited from not being a centred composition, but that''s just my take. Still, these guys can''t be all that easy to photograph in the wild!</td>', 'Seems a bit OOF to me. I think it would have benefited from not being a centred composition, but that''s just my take. Still, these guys can''t be all that easy to photograph in the wild!', '2014-04-16 13:10:59.000000', NULL, 1),
