(7204342, 1109227, 30608, '<td valign="top">After reviewing every photo in the challenge, this is by far my favorite. I hope you take first place. 10</td>', 'After reviewing every photo in the challenge, this is by far my favorite. I hope you take first place. 10', '2014-04-16 13:46:06.000000', NULL, 1),
(7204363, 1109340, 153814, '<td valign="top">Well done, looks like a NATGEO shot.</td>', 'Well done, looks like a NATGEO shot.', '2014-04-16 14:41:59.000000', NULL, 1),
(7204364, 1108883, 153814, '<td valign="top">Nice crisp shot, great detail.</td>', 'Nice crisp shot, great detail.', '2014-04-16 14:42:39.000000', NULL, 1),
