(7204477, 1109368, 114285, '<td valign="top">Amazing leg action, what an awesome capture, I feel the movement, top five.</td>', 'Amazing leg action, what an awesome capture, I feel the movement, top five.', '2014-04-16 21:06:58.000000', NULL, 1),
