(7205247, 1109368, 153814, '<td valign="top">Check ignition, ready for take off. That''s one big bird. <br/>Beautiful shot.</td>', 'Check ignition, ready for take off. That''s one big bird. Beautiful shot.', '2014-04-18 14:52:50.000000', NULL, 1),
(7205248, 1109422, 153814, '<td valign="top">WOW that''s one creepy shot. Well done, thanks for the nightmares. :)</td>', 'WOW that''s one creepy shot. Well done, thanks for the nightmares. :)', '2014-04-18 14:52:58.000000', NULL, 1),
(7205291, 1109298, 45004, '<td valign="top">I like the lighting giving plenty of detail and nice highlights. The shallow DOF really directs the eye.</td>', 'I like the lighting giving plenty of detail and nice highlights. The shallow DOF really directs the eye.', '2014-04-18 17:41:59.000000', NULL, 1),
(7205294, 1108966, 45004, '<td valign="top">I like the use of the foreground to add some warm color to the shot.</td>', 'I like the use of the foreground to add some warm color to the shot.', '2014-04-18 17:43:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7205296, 1109207, 45004, '<td valign="top">I love the colors and the focus.</td>', 'I love the colors and the focus.', '2014-04-18 17:46:08.000000', NULL, 1),
(7205297, 1108883, 45004, '<td valign="top">I like that the fox is bright and stands out against the dark background.</td>', 'I like that the fox is bright and stands out against the dark background.', '2014-04-18 17:55:31.000000', NULL, 1),
(7205336, 1109133, 86447, '<td valign="top">I''ve seen all of the entries.   I liked this one from the first for its rich colors and focus on the face. <br/> <br/>I hate to sound mean....  (really!  I do!), but...    This ... without seeing the competition... and knowing it was a zoo capture... would make me vote a 6.<br/> <br/>But... seeing the competition...   Now, it''s an 8 from me.<br/> <br/>I LOVE those rich colors.</td>', 'I''ve seen all of the entries.   I liked this one from the first for its rich colors and focus on the face.  I hate to sound mean....  (really!  I do!), but...    This ... without seeing the competition... and knowing it was a zoo capture... would make me vote a 6. But... seeing the competition...   Now, it''s an 8 from me. I LOVE those rich colors.', '2014-04-18 21:12:18.000000', NULL, 1),
(7205337, 1109228, 86447, '<td valign="top">I LOVE this image... IF there had been more room on the left of the image.  <br/> <br/>There''s no room for the face... the hairs are being cut off.<br/> <br/>It would score much higher, I think, if there were more space...   I love the focus on the eyes...  (Some don''t know to do that).<br/> <br/>Weighing it all in my pitiful brain... it''s a 7 from me.</td>', 'I LOVE this image... IF there had been more room on the left of the image.   There''s no room for the face... the hairs are being cut off. It would score much higher, I think, if there were more space...   I love the focus on the eyes...  (Some don''t know to do that). Weighing it all in my pitiful brain... it''s a 7 from me.', '2014-04-18 21:12:47.000000', NULL, 1),
(7205338, 1109088, 86447, '<td valign="top">Ha!  <br/> <br/>Love the fun!<br/> <br/> <br/>I don''t know about the negative space... seems like a closer crop would serve this image better... but... then it''s busy.<br/> <br/>I don''t know...  *sigh*   Giving it a 7 for now...</td>', 'Ha!   Love the fun!  I don''t know about the negative space... seems like a closer crop would serve this image better... but... then it''s busy. I don''t know...  *sigh*   Giving it a 7 for now...', '2014-04-18 21:13:03.000000', NULL, 1),
(7205339, 1109244, 86447, '<td valign="top">8 from me.</td>', '8 from me.', '2014-04-18 21:13:19.000000', NULL, 1),
(7205340, 1109340, 86447, '<td valign="top">7 from me</td>', '7 from me', '2014-04-18 21:13:41.000000', NULL, 1),
(7205341, 1109282, 86447, '<td valign="top">What a great capture!   There''s some odd yellow outline around the front and a few feathers of the wings... <br/> <br/>Still 8 from me.</td>', 'What a great capture!   There''s some odd yellow outline around the front and a few feathers of the wings...  Still 8 from me.', '2014-04-18 21:15:18.000000', NULL, 1),
(7205342, 1109135, 86447, '<td valign="top">7 from me.</td>', '7 from me.', '2014-04-18 21:15:27.000000', NULL, 1),
(7205345, 1109381, 86447, '<td valign="top">I think I''d have cropped out the green net... to make it more natural.  And the background is a bit noisy...<br/> <br/>It''a a wonderful capture, though.<br/> <br/>Still an 8 from me.</td>', 'I think I''d have cropped out the green net... to make it more natural.  And the background is a bit noisy... It''a a wonderful capture, though. Still an 8 from me.', '2014-04-18 21:17:02.000000', NULL, 1),
