(7205714, 1109424, 24454, '<td valign="top">This is so artful and beautiful! The black on black: exquisite!  I recently participated in an online animal photography workshop by Rachael McKenna.  Her favorite way to shoot animals is monochrome, especially black on black, and ever since I have been a huge fan of this look.  I really love this!</td>', 'This is so artful and beautiful! The black on black: exquisite!  I recently participated in an online animal photography workshop by Rachael McKenna.  Her favorite way to shoot animals is monochrome, especially black on black, and ever since I have been a huge fan of this look.  I really love this!', '2014-04-20 01:12:26.000000', NULL, 1),
(7205720, 1109056, 108580, '<td valign="top">Very 60''s film style in processing. I like the dawdling tardy interaction between the two younger foreground elephants and the older rear elephants already moving off to greener pastures. So typical of them in the bush but sadly the focus is way off any Elephant and appears to be only on the foreground shrubs. 6</td>', 'Very 60''s film style in processing. I like the dawdling tardy interaction between the two younger foreground elephants and the older rear elephants already moving off to greener pastures. So typical of them in the bush but sadly the focus is way off any Elephant and appears to be only on the foreground shrubs. 6', '2014-04-20 01:49:02.000000', NULL, 1),
(7205721, 1109244, 108580, '<td valign="top">These herons are widespread throughout the world. As far as I can tell they are native to every continent. Lovely interaction image well composed. It seems a bit soft but the light is also very dull perhaps reducing contrast and wow factor. Pleasant and believable "wild" image.</td>', 'These herons are widespread throughout the world. As far as I can tell they are native to every continent. Lovely interaction image well composed. It seems a bit soft but the light is also very dull perhaps reducing contrast and wow factor. Pleasant and believable "wild" image.', '2014-04-20 01:50:04.000000', NULL, 1),
(7205723, 1109457, 108580, '<td valign="top">Lovely interactive shot. Great effort. I''m a bit critical of the central composition and the over-exposed highlights. Focus seems a tad off on the eyes of the youngsters and the adult. Should be at least on the chicks in this case imo. Might be blur due a low shutter speed. 6</td>', 'Lovely interactive shot. Great effort. I''m a bit critical of the central composition and the over-exposed highlights. Focus seems a tad off on the eyes of the youngsters and the adult. Should be at least on the chicks in this case imo. Might be blur due a low shutter speed. 6', '2014-04-20 01:51:51.000000', NULL, 1),
(7205727, 1108966, 108580, '<td valign="top">Most unusual composition and inclusion of a large quantity of grasses/reeds in the FG. I actually quite like it and the gulls are obviously too early, spring has not quite sprung! It just needs a but more than the title to give it some Wildlife Wow. 6.</td>', 'Most unusual composition and inclusion of a large quantity of grasses/reeds in the FG. I actually quite like it and the gulls are obviously too early, spring has not quite sprung! It just needs a but more than the title to give it some Wildlife Wow. 6.', '2014-04-20 02:00:47.000000', NULL, 1),
(7205742, 1108877, 108580, '<td valign="top">A solid flight image and good sharpness on the eye and perfect shutter speed/aperture settings. A pity it is quartering away from you and not flying toward you... and the dark bill is lost in the shadow of the wave in the BG. 6.</td>', 'A solid flight image and good sharpness on the eye and perfect shutter speed/aperture settings. A pity it is quartering away from you and not flying toward you... and the dark bill is lost in the shadow of the wave in the BG. 6.', '2014-04-20 03:31:42.000000', NULL, 1),
(7205743, 1109464, 108580, '<td valign="top">Lovely spring image and nicely cropped (for compositional balance) although I fear too much crop which has lost you some definition. No obvious signs of the hand of man so a believable wildlife shot. 6.</td>', 'Lovely spring image and nicely cropped (for compositional balance) although I fear too much crop which has lost you some definition. No obvious signs of the hand of man so a believable wildlife shot. 6.', '2014-04-20 03:33:14.000000', NULL, 1),
(7205749, 1109207, 108580, '<td valign="top">Not easy to catch these guys they are normally quite nervous and flighty. They are so common place throughout Southern Africa and have taken well to the suburbs. Very sharp image with beautiful capture of the purple blue glimmer seldom seen as they are quite mobile and the shimmer is fleeting. Should do well on DPC, bright colourful, crisp.</td>', 'Not easy to catch these guys they are normally quite nervous and flighty. They are so common place throughout Southern Africa and have taken well to the suburbs. Very sharp image with beautiful capture of the purple blue glimmer seldom seen as they are quite mobile and the shimmer is fleeting. Should do well on DPC, bright colourful, crisp.', '2014-04-20 05:15:17.000000', NULL, 1),
(7205802, 1108839, 67258, '<td valign="top">This doesn''t seem to be a wildlife photo in the generally accepted sense - the fox has no wariness at all, which does make me wonder if it is captive or has been hand-reared.  However, the focus and dof are spot on - to have both ears, eyes and snout in focus, but the background soft is ideal. Light is a tad harsh, but overall a good portrait. In any event, I have tended to give higher marks to photos that show a bit of the animals natural habitat, or of its behaviour.</td>', 'This doesn''t seem to be a wildlife photo in the generally accepted sense - the fox has no wariness at all, which does make me wonder if it is captive or has been hand-reared.  However, the focus and dof are spot on - to have both ears, eyes and snout in focus, but the background soft is ideal. Light is a tad harsh, but overall a good portrait. In any event, I have tended to give higher marks to photos that show a bit of the animals natural habitat, or of its behaviour.', '2014-04-20 12:49:45.000000', NULL, 1),
(7205803, 1109047, 67258, '<td valign="top">An interesting portrait of this mallard; I appreciate the different take on it.  The light does seem as though it was a little on the bright side, but you have controlled the exposure well, and there is lots of detail, both of texture and colour.  It is such a shame that the shadow in the bottom left is there, but at least it isn''t masking the detail.</td>', 'An interesting portrait of this mallard; I appreciate the different take on it.  The light does seem as though it was a little on the bright side, but you have controlled the exposure well, and there is lots of detail, both of texture and colour.  It is such a shame that the shadow in the bottom left is there, but at least it isn''t masking the detail.', '2014-04-20 12:53:42.000000', NULL, 1),
(7205804, 1108903, 67258, '<td valign="top">A good wildlife photo of a common subject - not as easy to get as many would think.  Excellent portrayal of animal behaviour, with a title to match.</td>', 'A good wildlife photo of a common subject - not as easy to get as many would think.  Excellent portrayal of animal behaviour, with a title to match.', '2014-04-20 12:54:57.000000', NULL, 1),
(7205805, 1109160, 67258, '<td valign="top">Lol, made me laugh. Not a great wildlife photo, technically, but the photo so matches the title that it makes it work.</td>', 'Lol, made me laugh. Not a great wildlife photo, technically, but the photo so matches the title that it makes it work.', '2014-04-20 12:55:58.000000', NULL, 1),
(7205806, 1109060, 67258, '<td valign="top">A beautiful study - and the bird so perfectly placed, both in the frame and within the branches, with not a single branch obscuring it.  Good birding skills!</td>', 'A beautiful study - and the bird so perfectly placed, both in the frame and within the branches, with not a single branch obscuring it.  Good birding skills!', '2014-04-20 12:56:53.000000', NULL, 1),
(7205807, 1109365, 67258, '<td valign="top">Aww, I can see that eye! A sweet photo, showing the shyness of the bird.</td>', 'Aww, I can see that eye! A sweet photo, showing the shyness of the bird.', '2014-04-20 12:57:24.000000', NULL, 1),
(7205835, 1109016, 67258, '<td valign="top">I think I would prefer this if there was a little more space around the bison, it does feel very cramped within the constraints of the frame; I do like the inclusion of the second bison in the background, and would enjoy seeing more of the habitat.  On my monitor, the lower half of the bison is very dark, to the point that all detail is lost, and I almost find myself squinting. I am sure that more detail could be brought out, and would definitely be worthwhile.</td>', 'I think I would prefer this if there was a little more space around the bison, it does feel very cramped within the constraints of the frame; I do like the inclusion of the second bison in the background, and would enjoy seeing more of the habitat.  On my monitor, the lower half of the bison is very dark, to the point that all detail is lost, and I almost find myself squinting. I am sure that more detail could be brought out, and would definitely be worthwhile.', '2014-04-20 15:32:59.000000', NULL, 1),
(7205838, 1109194, 67258, '<td valign="top">This is clearly not a wildlife photograph in the generally accepted usage of the term; the cage is clearly visible. Lighting was clearly harsh, and parts of the bird are over-exposed.  Doesn''t work for me.</td>', 'This is clearly not a wildlife photograph in the generally accepted usage of the term; the cage is clearly visible. Lighting was clearly harsh, and parts of the bird are over-exposed.  Doesn''t work for me.', '2014-04-20 15:38:53.000000', NULL, 1),
(7205839, 1109388, 67258, '<td valign="top">At least you aren''t trying to pretend this is something it isn''t!  A pretty amazing floral display, although it does look like a strong wind would topple it over.  Gave me a smile.</td>', 'At least you aren''t trying to pretend this is something it isn''t!  A pretty amazing floral display, although it does look like a strong wind would topple it over.  Gave me a smile.', '2014-04-20 15:40:06.000000', NULL, 1),
(7205840, 1108765, 67258, '<td valign="top">Stunning.  Foxes, at least here in the UK, are notoriously shy (until they smell the chicken shed) and whilst I have come across them when walking, I have never been able to get a photograph.  Were you in a hide here?  A really lovely photograph that has a delightful intimacy to it.</td>', 'Stunning.  Foxes, at least here in the UK, are notoriously shy (until they smell the chicken shed) and whilst I have come across them when walking, I have never been able to get a photograph.  Were you in a hide here?  A really lovely photograph that has a delightful intimacy to it.', '2014-04-20 15:41:55.000000', NULL, 1),
(7205841, 1109283, 67258, '<td valign="top">Super balance to this composition.</td>', 'Super balance to this composition.', '2014-04-20 15:42:28.000000', NULL, 1),
(7205842, 1109172, 67258, '<td valign="top">Pretty, although I do get a slightly tilted feel.</td>', 'Pretty, although I do get a slightly tilted feel.', '2014-04-20 15:43:00.000000', NULL, 1),
(7205843, 1109153, 67258, '<td valign="top">An interesting photo of an animal I have only seen on nature documentaries.  The composition is good, and the wild flowers in the meadow add a sense of place and add appeal.  The pose of the elk works well, and shows its flightiness, muscles tensed ready to go.  On my screen it does look over-sharpened, and the exposure of the elk is on the dark side, but over-all I do like this photo.</td>', 'An interesting photo of an animal I have only seen on nature documentaries.  The composition is good, and the wild flowers in the meadow add a sense of place and add appeal.  The pose of the elk works well, and shows its flightiness, muscles tensed ready to go.  On my screen it does look over-sharpened, and the exposure of the elk is on the dark side, but over-all I do like this photo.', '2014-04-20 15:46:35.000000', NULL, 1),
(7205844, 1109465, 67258, '<td valign="top">Not very keen on your non-traditional processing. The eye is bright, but contrast negligible for the rest of the heron, meaning much of the detail is lost.</td>', 'Not very keen on your non-traditional processing. The eye is bright, but contrast negligible for the rest of the heron, meaning much of the detail is lost.', '2014-04-20 15:47:50.000000', NULL, 1),
(7205846, 1109198, 67258, '<td valign="top">Not enough detail for me, but the tones are pleasing.</td>', 'Not enough detail for me, but the tones are pleasing.', '2014-04-20 16:00:34.000000', NULL, 1),
(7205848, 1109261, 67258, '<td valign="top">Look at those eye-lashes!  The new growth does look very strange - I don''t think I have ever seen antler growth at this stage before, so an extra mark for that :)  I am intrigued how you were able to get a photo at such apparantly close quarters.  Deer here in England are notoriously hard to photograph as they are so flighty and timid.  I would maybe prefer a little more inclusion of environment.</td>', 'Look at those eye-lashes!  The new growth does look very strange - I don''t think I have ever seen antler growth at this stage before, so an extra mark for that :)  I am intrigued how you were able to get a photo at such apparantly close quarters.  Deer here in England are notoriously hard to photograph as they are so flighty and timid.  I would maybe prefer a little more inclusion of environment.', '2014-04-20 16:03:29.000000', NULL, 1),
(7205855, 1109422, 108580, '<td valign="top">This will (I hope) garner good votes. It''s eerie and really portrays the wild and dangerous nature of the animal. Great reflection too. There are no visible signs of the hand of man (man made objects) so whether it''s in a zoo or in the true wild is undetermined but I''ll give you the benefit of the doubt. Quite a "heavy" post process and what appears to be Topaz Labs Simplify? The characteristic of which gives a smooth and wavelike effect on croc/gator skin. The eye colour has thrown me; it''s normally very yellow. The dark background is well processed; smooth and black probably aided by either a considerable underexposure -2.0 EV or it''s a late afternoon/early evening shot. A good all round solid believable wildlife entry that ticks all the boxes of WILD-life including the obligatory "eye look" has been captured. 8.</td>', 'This will (I hope) garner good votes. It''s eerie and really portrays the wild and dangerous nature of the animal. Great reflection too. There are no visible signs of the hand of man (man made objects) so whether it''s in a zoo or in the true wild is undetermined but I''ll give you the benefit of the doubt. Quite a "heavy" post process and what appears to be Topaz Labs Simplify? The characteristic of which gives a smooth and wavelike effect on croc/gator skin. The eye colour has thrown me; it''s normally very yellow. The dark background is well processed; smooth and black probably aided by either a considerable underexposure -2.0 EV or it''s a late afternoon/early evening shot. A good all round solid believable wildlife entry that ticks all the boxes of WILD-life including the obligatory "eye look" has been captured. 8.', '2014-04-20 17:09:33.000000', NULL, 1),
(7205882, 1109453, 18367, '<td valign="top">This image must have been taken with a very long lens unless of course your Killdeer behave very differently than here.  Here, when one gets anywhere near their nest, they tend to run away from the nest and give you the broken wing thing, hoping you will follow them away from the nest.  <br/> <br/>Nice image, but the harsh sun really did not do you any favours.  Good luck in the challenge.</td>', 'This image must have been taken with a very long lens unless of course your Killdeer behave very differently than here.  Here, when one gets anywhere near their nest, they tend to run away from the nest and give you the broken wing thing, hoping you will follow them away from the nest.   Nice image, but the harsh sun really did not do you any favours.  Good luck in the challenge.', '2014-04-20 19:17:07.000000', NULL, 1),
(7205933, 1109133, 98339, '<td valign="top">I''m going to really go out on a limb here and guess that this is from the <a href="//www.tallahasseemagazine.com/March-April-2014/Floridas-Historic-Coast/" rel="nofollow" target="_blank">Jacksonville Zoo</a> I think it''s terribly coincidental that the Jaguar in the article has the identical BG as your picture. Such a shame as the animal is beautiful.<br/> <br/>As per the challenge description "For the purpose of this challenge, "wildlife" should be considered non-domesticated mammals, birds, reptiles and amphibians <i><b>living in a natural environment</b></i>. Now that you know what to photograph, take your best shot"!<br/> <br/>Having spent the last week "hunting wildlife" in my local area, risking injury, donating blood to the local mosquito blood banks.  I will be quite disappointed to find out that this is indeed taken at a Zoo.  No matter the beauty of the subject.</td>', 'I''m going to really go out on a limb here and guess that this is from the Jacksonville Zoo I think it''s terribly coincidental that the Jaguar in the article has the identical BG as your picture. Such a shame as the animal is beautiful. As per the challenge description "For the purpose of this challenge, "wildlife" should be considered non-domesticated mammals, birds, reptiles and amphibians living in a natural environment. Now that you know what to photograph, take your best shot"! Having spent the last week "hunting wildlife" in my local area, risking injury, donating blood to the local mosquito blood banks.  I will be quite disappointed to find out that this is indeed taken at a Zoo.  No matter the beauty of the subject.', '2014-04-20 21:45:20.000000', NULL, 1),
(7206082, 1108909, 102109, '<td valign="top">This is a marsupial, not a bear. :)</td>', 'This is a marsupial, not a bear. :)', '2014-04-21 03:58:08.000000', NULL, 1),
(7206102, 1109453, 67258, '<td valign="top">A close photo of this plover - possibly a bit too close!  A lower perspective, from lying on the ground would make for a stronger photo, I believe, but you have captured some of the bird''s natural behaviour, although a slightly wider shot would have allowed a bit more of the habitat to be included.</td>', 'A close photo of this plover - possibly a bit too close!  A lower perspective, from lying on the ground would make for a stronger photo, I believe, but you have captured some of the bird''s natural behaviour, although a slightly wider shot would have allowed a bit more of the habitat to be included.', '2014-04-21 05:51:58.000000', NULL, 1),
(7206103, 1108966, 67258, '<td valign="top">A rather sweet photograph.  I like the understated feel, both in composition and colour palette.</td>', 'A rather sweet photograph.  I like the understated feel, both in composition and colour palette.', '2014-04-21 05:52:50.000000', NULL, 1),
(7206104, 1109427, 67258, '<td valign="top">A really good portrait of this heron, with textural detail in the plumage.  Plenty of room for the bird to look into, and a view of it in its habitat.</td>', 'A really good portrait of this heron, with textural detail in the plumage.  Plenty of room for the bird to look into, and a view of it in its habitat.', '2014-04-21 05:53:54.000000', NULL, 1),
(7206106, 1109433, 67258, '<td valign="top">A shame you have cut of the claws of one of the sparrows.</td>', 'A shame you have cut of the claws of one of the sparrows.', '2014-04-21 05:54:56.000000', NULL, 1),
(7206111, 1109269, 67258, '<td valign="top">Lol, that is definitely ''in your face''!</td>', 'Lol, that is definitely ''in your face''!', '2014-04-21 05:58:17.000000', NULL, 1),
(7206112, 1109238, 67258, '<td valign="top">A nice study of this crow, but I do feel you could have pushed both the blacks and the contrast more.  A bit of a shame what looks like a dustbin lid is in the shot.</td>', 'A nice study of this crow, but I do feel you could have pushed both the blacks and the contrast more.  A bit of a shame what looks like a dustbin lid is in the shot.', '2014-04-21 05:59:27.000000', NULL, 1),
(7206114, 1109258, 67258, '<td valign="top">Like the title!  Looks like this was taken close to noon, looking at the shadow, so good control of exposure.  Shows that even in an urban setting there is wildlife to be found, and the brutal concrete and hard angles add to that sense.</td>', 'Like the title!  Looks like this was taken close to noon, looking at the shadow, so good control of exposure.  Shows that even in an urban setting there is wildlife to be found, and the brutal concrete and hard angles add to that sense.', '2014-04-21 06:01:28.000000', NULL, 1),
(7206115, 1109244, 67258, '<td valign="top">A lovely study, you have captured such an intimate moment with great sensitivity.  Both animal behaviour and habitat shown at their best.</td>', 'A lovely study, you have captured such an intimate moment with great sensitivity.  Both animal behaviour and habitat shown at their best.', '2014-04-21 06:02:32.000000', NULL, 1),
(7206116, 1109288, 67258, '<td valign="top">A cracking portrait of this elephant.  An incredibly hard exposure to get right given the clearly very bright sunlight, and you have nailed it.</td>', 'A cracking portrait of this elephant.  An incredibly hard exposure to get right given the clearly very bright sunlight, and you have nailed it.', '2014-04-21 06:03:46.000000', NULL, 1),
(7206117, 1108883, 67258, '<td valign="top">American foxes must be a great deal less wary than the European red fox - even in a hide I doubt you could get a shot this close.  Good dof and focus.</td>', 'American foxes must be a great deal less wary than the European red fox - even in a hide I doubt you could get a shot this close.  Good dof and focus.', '2014-04-21 06:05:10.000000', NULL, 1),
(7206129, 1109381, 153814, '<td valign="top">Great action shot. Looks like they have everything from netting to pinecones in there.</td>', 'Great action shot. Looks like they have everything from netting to pinecones in there.', '2014-04-21 08:05:11.000000', NULL, 1),
(7206130, 1108895, 153814, '<td valign="top">Great shot, very different from the rest of the field. That''s some red.<br/>Well done.</td>', 'Great shot, very different from the rest of the field. That''s some red.Well done.', '2014-04-21 08:08:45.000000', NULL, 1),
(7206131, 1109227, 114225, '<td valign="top">Wow, first image to vote on is beautiful!</td>', 'Wow, first image to vote on is beautiful!', '2014-04-21 08:11:52.000000', NULL, 1),
(7206132, 1109422, 114225, '<td valign="top">Such amazing deep mood.</td>', 'Such amazing deep mood.', '2014-04-21 08:12:10.000000', NULL, 1),
(7206136, 1109056, 135744, '<td valign="top">Wow what a capture. Not often you see 5 elephants in the wild.</td>', 'Wow what a capture. Not often you see 5 elephants in the wild.', '2014-04-21 08:46:05.000000', NULL, 1),
(7206188, 1108839, 116247, '<td valign="top">Ring-ding-ding-ding-dingeringeding!<br/>Gering-ding-ding-ding-dingeringeding!<br/>Gering-ding-ding-ding-dingeringeding!<br/>What the fox say? <br/> <br/>Thanks for getting the song stuckin my head!!! -1 for that and +1 becuase its a fox! ;) <br/> <br/>Great eyes!</td>', 'Ring-ding-ding-ding-dingeringeding!Gering-ding-ding-ding-dingeringeding!Gering-ding-ding-ding-dingeringeding!What the fox say?  Thanks for getting the song stuckin my head!!! -1 for that and +1 becuase its a fox! ;)  Great eyes!', '2014-04-21 11:17:09.000000', NULL, 1),
(7206189, 1109453, 116247, '<td valign="top">Oh I can here it now! I bet you that she wasn''t happy with you!</td>', 'Oh I can here it now! I bet you that she wasn''t happy with you!', '2014-04-21 11:17:54.000000', NULL, 1),
(7206190, 1109117, 116247, '<td valign="top">Oh my! Look at those little ones!</td>', 'Oh my! Look at those little ones!', '2014-04-21 11:18:43.000000', NULL, 1),
(7206191, 1109243, 116247, '<td valign="top">Meep Meep! Hurry up!!</td>', 'Meep Meep! Hurry up!!', '2014-04-21 11:20:40.000000', NULL, 1),
(7206194, 1109059, 116247, '<td valign="top">They eyes of an osprey!</td>', 'They eyes of an osprey!', '2014-04-21 11:22:34.000000', NULL, 1),
(7206197, 1109088, 116247, '<td valign="top">Wow! Brilliant, fabulous, awesome! Love it! 10!</td>', 'Wow! Brilliant, fabulous, awesome! Love it! 10!', '2014-04-21 11:27:33.000000', NULL, 1),
(7206234, 1109259, 67258, '<td valign="top">Super portrait with a good sense of environment and behaviour.  Woodpeckers in Britain tend to be very shy and quite hard to photograph, impressed!<br/>Just back to say that I spent a couple of days camping this week, and saw my first ever Green Woodpecker - very excited!  Looking at your photo again, I do spot a rather obvious line along the chest where you have masked.  I''m no good at masking at all, but after the challenge you may want to revisit the photo to fine tune a bit more, because it really is cracking.  Not changing my initial score.</td>', 'Super portrait with a good sense of environment and behaviour.  Woodpeckers in Britain tend to be very shy and quite hard to photograph, impressed!Just back to say that I spent a couple of days camping this week, and saw my first ever Green Woodpecker - very excited!  Looking at your photo again, I do spot a rather obvious line along the chest where you have masked.  I''m no good at masking at all, but after the challenge you may want to revisit the photo to fine tune a bit more, because it really is cracking.  Not changing my initial score.', '2014-04-21 12:57:28.000000', NULL, 1),
(7206235, 1109056, 67258, '<td valign="top">Refreshing to see what I take to be a genuine African wildlife photograph.  The composition is very well balanced, and I love the inclusion of the retreating elephants - it gives an excellent feeling of ''herd''.  I am not so sure about the sepia toning; it gives the photo a somewhat muddy and flat feel, which is a great shame given that there is detail throughout.</td>', 'Refreshing to see what I take to be a genuine African wildlife photograph.  The composition is very well balanced, and I love the inclusion of the retreating elephants - it gives an excellent feeling of ''herd''.  I am not so sure about the sepia toning; it gives the photo a somewhat muddy and flat feel, which is a great shame given that there is detail throughout.', '2014-04-21 12:58:33.000000', NULL, 1),
(7206236, 1109340, 67258, '<td valign="top">Aww, I do love photos of seals - I''m not sure whether you have caught this one mid-blink, if it has a cataract, or if there is strong reflection from the sky, but the right eye does look clouded or blind, which I find mildly distracting.  I might have been tempted to try for a shallower dof, but respect your choice.</td>', 'Aww, I do love photos of seals - I''m not sure whether you have caught this one mid-blink, if it has a cataract, or if there is strong reflection from the sky, but the right eye does look clouded or blind, which I find mildly distracting.  I might have been tempted to try for a shallower dof, but respect your choice.', '2014-04-21 12:58:36.000000', NULL, 1),
(7206242, 1109227, 108580, '<td valign="top">I like this shot a lot. The oft ignored Impala. It''s seldom photographed in Africa as it is so common here. It''s clean and crisp and nicely composed. The "look" is wonderful and the exposure perfect. <br/>However as a wildlife photographer and purist, all of this is sadly spoiled by what appears to be the hand of man in a wildlife shot; symmetrical light grey concrete rubble in front of what appears to be a partial visible tyre and a fence pole behind the animals rump in the background :( I''m sorry if you feel this is harsh however true WILD-life photography has none of these things (man made objects) in it. This is the difference between wildlife and nature categories, although it is extremely hard to police in photo competitions except by self regulation and honesty as with cropping or better composition these things can be avoided in reserves to make it appear as if it was taken in the animals natural and true but ever shrinking wild habitat.<br/> <br/>DPC does not have a wildlife category so this challenge is rather amusing from that aspect.</td>', 'I like this shot a lot. The oft ignored Impala. It''s seldom photographed in Africa as it is so common here. It''s clean and crisp and nicely composed. The "look" is wonderful and the exposure perfect. However as a wildlife photographer and purist, all of this is sadly spoiled by what appears to be the hand of man in a wildlife shot; symmetrical light grey concrete rubble in front of what appears to be a partial visible tyre and a fence pole behind the animals rump in the background :( I''m sorry if you feel this is harsh however true WILD-life photography has none of these things (man made objects) in it. This is the difference between wildlife and nature categories, although it is extremely hard to police in photo competitions except by self regulation and honesty as with cropping or better composition these things can be avoided in reserves to make it appear as if it was taken in the animals natural and true but ever shrinking wild habitat. DPC does not have a wildlife category so this challenge is rather amusing from that aspect.', '2014-04-21 13:22:22.000000', NULL, 1),
(7206260, 1109149, 67258, '<td valign="top">Perfect depth of field, focus and exposure.  Sweet photo of a cute subject - although the grey squirrel isn''t universally loved in England as the pox virus it brought with it has all but decimated the native red squirrel.   This is crying out for the addition of a speech bubble!</td>', 'Perfect depth of field, focus and exposure.  Sweet photo of a cute subject - although the grey squirrel isn''t universally loved in England as the pox virus it brought with it has all but decimated the native red squirrel.   This is crying out for the addition of a speech bubble!', '2014-04-21 13:51:54.000000', NULL, 1),
(7206262, 1108909, 67258, '<td valign="top">Aww, super sweet - oops, wrong challenge!  But it is....</td>', 'Aww, super sweet - oops, wrong challenge!  But it is....', '2014-04-21 13:52:29.000000', NULL, 1),
(7206265, 1109457, 67258, '<td valign="top">Aww, an interesting wildlife photo, showing bird behaviour.  A shame the parents head is a little blurred, possibly from movement as other parts on the same focal plane seem sharp.</td>', 'Aww, an interesting wildlife photo, showing bird behaviour.  A shame the parents head is a little blurred, possibly from movement as other parts on the same focal plane seem sharp.', '2014-04-21 14:00:33.000000', NULL, 1),
(7206266, 1109420, 67258, '<td valign="top">An unusual, but perfectly valid take on the subject.  I rather like this.</td>', 'An unusual, but perfectly valid take on the subject.  I rather like this.', '2014-04-21 14:01:17.000000', NULL, 1),
(7206268, 1109373, 67258, '<td valign="top">Super study of the duck - crisp focus, excellent exposure, and a sense of motion.  My only niggle is that I would prefer either no background, or more background.  The yellow streak, all be it well softened, is rather distracting.</td>', 'Super study of the duck - crisp focus, excellent exposure, and a sense of motion.  My only niggle is that I would prefer either no background, or more background.  The yellow streak, all be it well softened, is rather distracting.', '2014-04-21 14:03:08.000000', NULL, 1),
(7206269, 1109067, 67258, '<td valign="top">A good photo of this woodpecker, not obscured by twigs or foliage.</td>', 'A good photo of this woodpecker, not obscured by twigs or foliage.', '2014-04-21 14:04:49.000000', NULL, 1),
(7206271, 1109228, 67258, '<td valign="top">Lovely.  I have a few photos of Exmoor ponies - not as easy as people might think.  I love driving over the moor trying to spot them.  Black and white was a good choice, I feel.</td>', 'Lovely.  I have a few photos of Exmoor ponies - not as easy as people might think.  I love driving over the moor trying to spot them.  Black and white was a good choice, I feel.', '2014-04-21 14:06:19.000000', NULL, 1),
(7206272, 1109464, 67258, '<td valign="top">A pretty study of a bird I have never come across.  Pleasing that the bird is not obscured by twigs or foliage.  My only criticism is that it looks a tad soft and lacking in contrast.</td>', 'A pretty study of a bird I have never come across.  Pleasing that the bird is not obscured by twigs or foliage.  My only criticism is that it looks a tad soft and lacking in contrast.', '2014-04-21 14:07:33.000000', NULL, 1),
(7206334, 1108946, 108580, '<td valign="top">Lovely crisp shot and well exposed, great sky. Just lacking a catch-light so critical to BiF or most bird photography today. Completely void of human structures and objects so technically accurate in terms of WILD-life. Despite the image likely being taken at a dock, wharf or the seaside. The animal is non-captive but probably acclimatised to humans.</td>', 'Lovely crisp shot and well exposed, great sky. Just lacking a catch-light so critical to BiF or most bird photography today. Completely void of human structures and objects so technically accurate in terms of WILD-life. Despite the image likely being taken at a dock, wharf or the seaside. The animal is non-captive but probably acclimatised to humans.', '2014-04-21 15:49:01.000000', NULL, 1),
(7206335, 1109261, 108580, '<td valign="top">Very pretty entry and complimentary tones in the deer and it''s background. No signs of man made structures or obstructions. Crisp clear eyes and good DOF. You''ve managed to get quite close to the animal so it must be very acclimatised to humans, perhaps in a reserve or park. Possibly captive from this perspective however that''s not necessarily grounds for a DQ or DNMC as the challenge requirement is quite vague. DPC doesn''t even have a Wildlife Category, only Nature and they are two quite different meanings and interpretations.</td>', 'Very pretty entry and complimentary tones in the deer and it''s background. No signs of man made structures or obstructions. Crisp clear eyes and good DOF. You''ve managed to get quite close to the animal so it must be very acclimatised to humans, perhaps in a reserve or park. Possibly captive from this perspective however that''s not necessarily grounds for a DQ or DNMC as the challenge requirement is quite vague. DPC doesn''t even have a Wildlife Category, only Nature and they are two quite different meanings and interpretations.', '2014-04-21 15:53:05.000000', NULL, 1),
(7206339, 1108790, 108580, '<td valign="top">Super crisp image, wonderful colours and moment caught. Sharp eye and obligatory catch-light. Pity about the OOF stalk in front of the bird. That''s wildlife photography! Uncontrollable and impossible to direct.</td>', 'Super crisp image, wonderful colours and moment caught. Sharp eye and obligatory catch-light. Pity about the OOF stalk in front of the bird. That''s wildlife photography! Uncontrollable and impossible to direct.', '2014-04-21 15:58:34.000000', NULL, 1),
(7206350, 1109424, 108580, '<td valign="top">Native of Australia. Beautiful birds. Interesting choice to go B&amp;W. Good composition. I quite like them offset against a colourful background however and the red bill then adds to it''s beauty. Whilst not endangered they are rare in the wild but commonplace around human habitation. The challenge is rather vague so no loss of points for that. In B&amp;W I feel it could do with a bit more contrast and deeper blacks.</td>', 'Native of Australia. Beautiful birds. Interesting choice to go B&W. Good composition. I quite like them offset against a colourful background however and the red bill then adds to it''s beauty. Whilst not endangered they are rare in the wild but commonplace around human habitation. The challenge is rather vague so no loss of points for that. In B&W I feel it could do with a bit more contrast and deeper blacks.', '2014-04-21 16:09:11.000000', NULL, 1),
(7206356, 1109227, 175475, '<td valign="top">What a beautiful photo. I love the sharpness and the colour.</td>', 'What a beautiful photo. I love the sharpness and the colour.', '2014-04-21 16:24:47.000000', NULL, 1),
(7206357, 1109383, 175475, '<td valign="top">Beautiful colour and detail.</td>', 'Beautiful colour and detail.', '2014-04-21 16:25:03.000000', NULL, 1),
(7206358, 1109288, 175475, '<td valign="top">This photo is just beautiful.</td>', 'This photo is just beautiful.', '2014-04-21 16:25:28.000000', NULL, 1),
(7206359, 1108987, 175475, '<td valign="top">I adore this photo! There is just something about the way the little guy is poking his head around that tree. What a great moment!</td>', 'I adore this photo! There is just something about the way the little guy is poking his head around that tree. What a great moment!', '2014-04-21 16:26:15.000000', NULL, 1),
(7206360, 1108946, 175475, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2014-04-21 16:26:28.000000', NULL, 1),
(7206394, 1109227, 147314, '<td valign="top">Beautiful. I like the contrast in colours and also the contrast in sharpness of the animal and the blurry background.</td>', 'Beautiful. I like the contrast in colours and also the contrast in sharpness of the animal and the blurry background.', '2014-04-21 18:01:29.000000', NULL, 1),
(7206395, 1108883, 147314, '<td valign="top">Great image: good focus, nice colours and bokeh.</td>', 'Great image: good focus, nice colours and bokeh.', '2014-04-21 18:02:17.000000', NULL, 1),
(7206396, 1109298, 147314, '<td valign="top">Very different from the rest of the images but really cool. Personally I like the toning, might even stand out more than in colour. Only small remark is that smudge in the upper-right corner.</td>', 'Very different from the rest of the images but really cool. Personally I like the toning, might even stand out more than in colour. Only small remark is that smudge in the upper-right corner.', '2014-04-21 18:10:25.000000', NULL, 1),
(7206398, 1109149, 147314, '<td valign="top">Lovely portrait of a lovely animal. Background processing looks a bit overdone, but I do like that to be honest.</td>', 'Lovely portrait of a lovely animal. Background processing looks a bit overdone, but I do like that to be honest.', '2014-04-21 18:12:04.000000', NULL, 1),
(7206399, 1109060, 114225, '<td valign="top">This is a shot where the vignette really helps.</td>', 'This is a shot where the vignette really helps.', '2014-04-21 18:12:20.000000', NULL, 1),
(7206401, 1109272, 147314, '<td valign="top">Lovely light makes this one a beautiful image. Well done!</td>', 'Lovely light makes this one a beautiful image. Well done!', '2014-04-21 18:13:11.000000', NULL, 1),
(7206402, 1109088, 114225, '<td valign="top">Great use of dof.</td>', 'Great use of dof.', '2014-04-21 18:13:29.000000', NULL, 1),
(7206405, 1109244, 147314, '<td valign="top">Really beautiful. I do like the composition, the interaction between the two and the way they really stand out against that dark background (great DoF)!</td>', 'Really beautiful. I do like the composition, the interaction between the two and the way they really stand out against that dark background (great DoF)!', '2014-04-21 18:15:19.000000', NULL, 1),
(7206406, 1108946, 147314, '<td valign="top">Very well exposed and processed, beautiful!</td>', 'Very well exposed and processed, beautiful!', '2014-04-21 18:16:06.000000', NULL, 1),
(7206411, 1109420, 108580, '<td valign="top">A very beautiful minimalist image which I like a lot. Sadly the wire is man made and as a wildlife photographer I believe the hand of man should not appear in a wildlife image-challenge even if the animal is non domesticated. Bumped to 6 as the challenge interpretation is rather vague and open ended.</td>', 'A very beautiful minimalist image which I like a lot. Sadly the wire is man made and as a wildlife photographer I believe the hand of man should not appear in a wildlife image-challenge even if the animal is non domesticated. Bumped to 6 as the challenge interpretation is rather vague and open ended.', '2014-04-21 18:18:50.000000', NULL, 1),
(7206412, 1109269, 147314, '<td valign="top">Not many times you get a chance to look it in the eyes as in this image, really special.</td>', 'Not many times you get a chance to look it in the eyes as in this image, really special.', '2014-04-21 18:19:16.000000', NULL, 1),
(7206413, 1108778, 108580, '<td valign="top">I don''t like the hand of man (man made objects) in a WILD-life challenge. However the birds are "non-domesticated" and it''s cleverly titled. DMC wrt to the birds but the structure makes this "nature" not "wildlife" imo.</td>', 'I don''t like the hand of man (man made objects) in a WILD-life challenge. However the birds are "non-domesticated" and it''s cleverly titled. DMC wrt to the birds but the structure makes this "nature" not "wildlife" imo.', '2014-04-21 18:21:02.000000', NULL, 1),
(7206415, 1108909, 147314, '<td valign="top">This is adorable, lovely. Not sure what to make of that lighter part underneath him; is it light or caused by processing?</td>', 'This is adorable, lovely. Not sure what to make of that lighter part underneath him; is it light or caused by processing?', '2014-04-21 18:21:59.000000', NULL, 1),
(7206416, 1109088, 147314, '<td valign="top">One of my favourite birds, really love those eyes. Good focus on it as well.</td>', 'One of my favourite birds, really love those eyes. Good focus on it as well.', '2014-04-21 18:23:41.000000', NULL, 1),
(7206432, 1109288, 15711, '<td valign="top">Love the branch in front of his trunk.  Lovely. :D</td>', 'Love the branch in front of his trunk.  Lovely. :D', '2014-04-21 18:39:41.000000', NULL, 1),
(7206433, 1109272, 15711, '<td valign="top">This is just beautiful.  I love the shadow tones.  NICE!! 8</td>', 'This is just beautiful.  I love the shadow tones.  NICE!! 8', '2014-04-21 18:40:34.000000', NULL, 1),
(7206436, 1109227, 15711, '<td valign="top">WOW  that is just amazingly wonderful. 10</td>', 'WOW  that is just amazingly wonderful. 10', '2014-04-21 18:43:23.000000', NULL, 1),
(7206499, 1109227, 97225, '<td valign="top">Exquisite! The composition is perfect, the posture of the deer, with its head turned to face you is perfect. The whole image is flavoured with enchantment. Stand alone top pick. 10. Fave.</td>', 'Exquisite! The composition is perfect, the posture of the deer, with its head turned to face you is perfect. The whole image is flavoured with enchantment. Stand alone top pick. 10. Fave.', '2014-04-21 21:35:56.000000', NULL, 1),
(7206501, 1109207, 97225, '<td valign="top">Beautiful image. The iridescent colours are magnificent and the lovely background shows the bird off to perfection. A ribbon choice from me.</td>', 'Beautiful image. The iridescent colours are magnificent and the lovely background shows the bird off to perfection. A ribbon choice from me.', '2014-04-21 21:39:11.000000', NULL, 1),
(7206502, 1109381, 97225, '<td valign="top">Superb capture! One of my ribbon choices.Interesting to see that the ospreys are into recycling.</td>', 'Superb capture! One of my ribbon choices.Interesting to see that the ospreys are into recycling.', '2014-04-21 21:40:32.000000', NULL, 1),
(7206505, 1109443, 103142, '<td valign="top">bumping -- there''s a lot of wonderful in this. :)</td>', 'bumping -- there''s a lot of wonderful in this. :)', '2014-04-21 22:08:58.000000', NULL, 1),
(7206527, 1108895, 108580, '<td valign="top">Beautiful exposure, greens and red and blacks very well represented and accurate. Focus appears to be on the lady birds back (reflection) and not the "eyes" or front mandible area. Not fond of the eye catching grasses leading from middle left into the picture nor the wood "railing" (?) or hand of man (man made object) in a "Wildlife" challenge. Wildlife photography avoids these things, and presents wildlife without it, even whilst it is becoming more difficult to find true wild in it''s shrinking environment. Although the challenge description gives some leeway in this regard I am a purist. There is a difference between a nature image (non or captive animal in a man made environment) and a wildlife image even though your subject is wild and obviously not captive.</td>', 'Beautiful exposure, greens and red and blacks very well represented and accurate. Focus appears to be on the lady birds back (reflection) and not the "eyes" or front mandible area. Not fond of the eye catching grasses leading from middle left into the picture nor the wood "railing" (?) or hand of man (man made object) in a "Wildlife" challenge. Wildlife photography avoids these things, and presents wildlife without it, even whilst it is becoming more difficult to find true wild in it''s shrinking environment. Although the challenge description gives some leeway in this regard I am a purist. There is a difference between a nature image (non or captive animal in a man made environment) and a wildlife image even though your subject is wild and obviously not captive.', '2014-04-22 01:16:52.000000', NULL, 1),
(7206553, 1109056, 114285, '<td valign="top">Stunning conversion to sepia tones, this is has to be right up there bump.</td>', 'Stunning conversion to sepia tones, this is has to be right up there bump.', '2014-04-22 03:36:27.000000', NULL, 1),
(7206554, 1109227, 114285, '<td valign="top">Stunning, and you know it! <br/> <br/>Bump!<br/> <br/>Pretty sure this will be the blue!</td>', 'Stunning, and you know it!  Bump! Pretty sure this will be the blue!', '2014-04-22 03:37:17.000000', NULL, 1),
(7206555, 1108946, 114285, '<td valign="top">Lovely POV, well done. Top ten for me.</td>', 'Lovely POV, well done. Top ten for me.', '2014-04-22 03:37:51.000000', NULL, 1),
(7206556, 1109288, 114285, '<td valign="top">Wonderful shot.</td>', 'Wonderful shot.', '2014-04-22 03:38:33.000000', NULL, 1),
(7206557, 1109398, 114285, '<td valign="top">Amazing editing give this a magical look. Bump!</td>', 'Amazing editing give this a magical look. Bump!', '2014-04-22 03:38:59.000000', NULL, 1),
(7206558, 1109228, 114285, '<td valign="top">gorgeous, don''t forget to darken the highlights next time :)</td>', 'gorgeous, don''t forget to darken the highlights next time :)', '2014-04-22 03:40:39.000000', NULL, 1),
(7206559, 1109284, 114285, '<td valign="top">LOl, what a sloth!</td>', 'LOl, what a sloth!', '2014-04-22 03:40:58.000000', NULL, 1),
(7206585, 1108897, 147314, '<td valign="top">Best of the heron images IMO. Love the composition, POV and sharpness, great image.</td>', 'Best of the heron images IMO. Love the composition, POV and sharpness, great image.', '2014-04-22 05:35:38.000000', NULL, 1),
(7206587, 1109068, 147314, '<td valign="top">I think this could have been a great image when focus was spot on, but somehow I can''t find that in-focus-point in this image. Composition might have improved with another crop, a bit more off-center.</td>', 'I think this could have been a great image when focus was spot on, but somehow I can''t find that in-focus-point in this image. Composition might have improved with another crop, a bit more off-center.', '2014-04-22 05:38:42.000000', NULL, 1),
(7206588, 1108794, 147314, '<td valign="top">A beautiful model, but somehow I don''t find this image attractive, probably a combination of exposure, composition and background.</td>', 'A beautiful model, but somehow I don''t find this image attractive, probably a combination of exposure, composition and background.', '2014-04-22 05:42:29.000000', NULL, 1),
(7206589, 1109135, 147314, '<td valign="top">Beautifully coloured birds, I only think you should have concentrated on just one of the two groups, providing less background.</td>', 'Beautifully coloured birds, I only think you should have concentrated on just one of the two groups, providing less background.', '2014-04-22 05:44:22.000000', NULL, 1),
(7206590, 1109465, 147314, '<td valign="top">Great catch, but I''m afraid the processing is not to my liking.</td>', 'Great catch, but I''m afraid the processing is not to my liking.', '2014-04-22 05:47:39.000000', NULL, 1),
(7206596, 1109381, 147314, '<td valign="top">Beautiful, love the details in those ospreys, so well focused!</td>', 'Beautiful, love the details in those ospreys, so well focused!', '2014-04-22 06:43:47.000000', NULL, 1),
(7206760, 1109413, 67258, '<td valign="top">Certainly a different take, but not one that really works for me.</td>', 'Certainly a different take, but not one that really works for me.', '2014-04-22 14:00:10.000000', NULL, 1),
(7206761, 1109274, 67258, '<td valign="top">A good choice of dof, but the background is still too distracting for me, particularly the car.  The tones of the bird are so similar to the background that it prevents it from standing out.  I wish the bird was facing with at least part of its front showing.</td>', 'A good choice of dof, but the background is still too distracting for me, particularly the car.  The tones of the bird are so similar to the background that it prevents it from standing out.  I wish the bird was facing with at least part of its front showing.', '2014-04-22 14:02:35.000000', NULL, 1),
(7206763, 1109369, 67258, '<td valign="top">Now that is an animal we don''t see photos of very often!  Looks like you might have just missed with the sharpest point of focus - I have no idea how fast beavers move or how elusive they are, though.  An extra point for spotting an unusual animal.</td>', 'Now that is an animal we don''t see photos of very often!  Looks like you might have just missed with the sharpest point of focus - I have no idea how fast beavers move or how elusive they are, though.  An extra point for spotting an unusual animal.', '2014-04-22 14:04:44.000000', NULL, 1),
(7206767, 1109111, 67258, '<td valign="top">A delightful photo, but one that I am confident has been taken in a zoo, given that ring tailed Lemurs are only found in the wild in small parts of Madagascar. My vote is adjusted down by 4 points to take account of the fact that the animals are captive.  If I am wrong, and they are indeed wild I would be delighted to change the score.</td>', 'A delightful photo, but one that I am confident has been taken in a zoo, given that ring tailed Lemurs are only found in the wild in small parts of Madagascar. My vote is adjusted down by 4 points to take account of the fact that the animals are captive.  If I am wrong, and they are indeed wild I would be delighted to change the score.', '2014-04-22 14:20:08.000000', NULL, 1),
(7206768, 1109417, 67258, '<td valign="top">A good pose from you model, and well placed within its habitat, but the lack of textural detail and the softness of the neck and head do detract quite considerably.</td>', 'A good pose from you model, and well placed within its habitat, but the lack of textural detail and the softness of the neck and head do detract quite considerably.', '2014-04-22 14:23:49.000000', NULL, 1),
(7206769, 1109470, 67258, '<td valign="top">Interesting, shrp, good dof, and lovely silky water.  I wonder what a slightly wider shot would have looked like?</td>', 'Interesting, shrp, good dof, and lovely silky water.  I wonder what a slightly wider shot would have looked like?', '2014-04-22 14:24:50.000000', NULL, 1),
(7206770, 1108803, 67258, '<td valign="top">A good depth of field, but you need to work on your focussing.</td>', 'A good depth of field, but you need to work on your focussing.', '2014-04-22 14:25:36.000000', NULL, 1),
(7206777, 1109432, 67258, '<td valign="top">The placement of the duck in the lower right corner works, and properly shows it in its natural habitat.  The photo is let down though, by a lack of detail in the duck itself and the blocking out of the deep shadow areas.  You may have been able to get a better photo by moving down to the same level as the duck, rather than by taking it from above.</td>', 'The placement of the duck in the lower right corner works, and properly shows it in its natural habitat.  The photo is let down though, by a lack of detail in the duck itself and the blocking out of the deep shadow areas.  You may have been able to get a better photo by moving down to the same level as the duck, rather than by taking it from above.', '2014-04-22 14:47:32.000000', NULL, 1),
(7206782, 1109422, 67258, '<td valign="top">Janine, this has grown on me over the course of the week - I do wish the nose (snout?) was in focus, but given that this was taken in the dead of night, it is pretty impressive.  Not voting.</td>', 'Janine, this has grown on me over the course of the week - I do wish the nose (snout?) was in focus, but given that this was taken in the dead of night, it is pretty impressive.  Not voting.', '2014-04-22 14:49:01.000000', NULL, 1),
(7206799, 1109177, 67258, '<td valign="top">A mink?  Has something of an unplanned feel to the shot - particular the way it is shot from above.  Nonetheless, pleasing to see a relatively unusual and hard to photograph mammal in the challenge.</td>', 'A mink?  Has something of an unplanned feel to the shot - particular the way it is shot from above.  Nonetheless, pleasing to see a relatively unusual and hard to photograph mammal in the challenge.', '2014-04-22 15:34:28.000000', NULL, 1),
(7206800, 1109303, 67258, '<td valign="top">If it wasn''t for the inclusion of the low sun in the shot and the placement of the silhouetted tree, this would be dreadful.  As it is, you have managed to raise it to something poetic.  It is a bit of a shame that the gulls aren''t a little clearer or crisper.</td>', 'If it wasn''t for the inclusion of the low sun in the shot and the placement of the silhouetted tree, this would be dreadful.  As it is, you have managed to raise it to something poetic.  It is a bit of a shame that the gulls aren''t a little clearer or crisper.', '2014-04-22 15:36:26.000000', NULL, 1),
(7206801, 1109135, 67258, '<td valign="top">Bluebird chicks?  We don''t have any birds as delightfully coloured as this in the UK.  I assume these are fledglings that have just left the nest and are at their most vulnerable, hence your title.  Clarity is lacking a bit.</td>', 'Bluebird chicks?  We don''t have any birds as delightfully coloured as this in the UK.  I assume these are fledglings that have just left the nest and are at their most vulnerable, hence your title.  Clarity is lacking a bit.', '2014-04-22 15:38:35.000000', NULL, 1),
(7206810, 1109383, 67258, '<td valign="top">I have no idea what this bird is - or where it might be found - I am going to hazard south Africa or maybe New Zealand? Super crisp focus, good textural detail, lovely curves to the composition and the light bokeh a super foil to the bird.</td>', 'I have no idea what this bird is - or where it might be found - I am going to hazard south Africa or maybe New Zealand? Super crisp focus, good textural detail, lovely curves to the composition and the light bokeh a super foil to the bird.', '2014-04-22 16:11:10.000000', NULL, 1),
(7206812, 1109398, 67258, '<td valign="top">The light and rays are pretty, but the ducks do seem to play second fiddle to them.  If there were a little more detail and clarity to the ducks I would have scored higher.</td>', 'The light and rays are pretty, but the ducks do seem to play second fiddle to them.  If there were a little more detail and clarity to the ducks I would have scored higher.', '2014-04-22 16:19:33.000000', NULL, 1),
(7206821, 1109243, 67258, '<td valign="top">Squirrels and their antics are such good fun.  Nice catch with the pair, but does have something of a snapshot feel.</td>', 'Squirrels and their antics are such good fun.  Nice catch with the pair, but does have something of a snapshot feel.', '2014-04-22 16:52:54.000000', NULL, 1),
(7206822, 1109452, 67258, '<td valign="top">A good catch of these wild foals playing and displaying natural behaviour.  Light does look a bit harsh.</td>', 'A good catch of these wild foals playing and displaying natural behaviour.  Light does look a bit harsh.', '2014-04-22 16:54:30.000000', NULL, 1),
(7206823, 1108778, 67258, '<td valign="top">Lol. The photo could  do with a bit more textural detail on the gulls and metal, but the silkiness of the water is very pleasing.</td>', 'Lol. The photo could  do with a bit more textural detail on the gulls and metal, but the silkiness of the water is very pleasing.', '2014-04-22 16:56:41.000000', NULL, 1),
(7206824, 1109381, 67258, '<td valign="top">Good strong photo of this pair of ospreys. The detail in the nest is fascinating.</td>', 'Good strong photo of this pair of ospreys. The detail in the nest is fascinating.', '2014-04-22 16:58:00.000000', NULL, 1),
(7206825, 1109062, 67258, '<td valign="top">A tad over exposed, with the whites of the cheek lacking any detail.  The inclusion of the stream gives context, but I might prefer a little more space for the heron, especially at the top of the frame.</td>', 'A tad over exposed, with the whites of the cheek lacking any detail.  The inclusion of the stream gives context, but I might prefer a little more space for the heron, especially at the top of the frame.', '2014-04-22 17:00:55.000000', NULL, 1),
(7206827, 1109122, 67258, '<td valign="top">The framing of this, and the colours of the sky don''t work for me.</td>', 'The framing of this, and the colours of the sky don''t work for me.', '2014-04-22 17:02:08.000000', NULL, 1),
(7206854, 1109282, 67258, '<td valign="top">There is something quite strange going on with this image - the owl almost looks superimposed on the background. I suspectthat you have processed the owl and background separately and some of the mask has crept over the edge in places.</td>', 'There is something quite strange going on with this image - the owl almost looks superimposed on the background. I suspectthat you have processed the owl and background separately and some of the mask has crept over the edge in places.', '2014-04-22 17:25:43.000000', NULL, 1),
(7206857, 1109059, 67258, '<td valign="top">Wild or captive?  A key question for me - if this is a genuinely wild bird in its natural habitat I am very impressed at you skill at getting so close.  I do wish that you had shown the whole of the bird - it seems strange to have a photo of this quality composed in such a way as to show just 4/5ths of the bird.</td>', 'Wild or captive?  A key question for me - if this is a genuinely wild bird in its natural habitat I am very impressed at you skill at getting so close.  I do wish that you had shown the whole of the bird - it seems strange to have a photo of this quality composed in such a way as to show just 4/5ths of the bird.', '2014-04-22 17:29:24.000000', NULL, 1),
(7206863, 1109387, 67258, '<td valign="top">A pleasing photo of this coot.  The inclusion of the reeds give a good indication of its natural habitat.  The light looks as though it was quite harsh, and the highlights on the bird''s head seem blown.</td>', 'A pleasing photo of this coot.  The inclusion of the reeds give a good indication of its natural habitat.  The light looks as though it was quite harsh, and the highlights on the bird''s head seem blown.', '2014-04-22 17:31:17.000000', NULL, 1),
(7206864, 1109298, 67258, '<td valign="top">An artistic take on the challenge, and it works fairly well for me.</td>', 'An artistic take on the challenge, and it works fairly well for me.', '2014-04-22 17:31:47.000000', NULL, 1),
(7206866, 1109289, 67258, '<td valign="top">Oh, that is an unexpected photo!  A really pleasing study of this tortoise (or is it a turtle?)  The very low viewpoint works well, giving the viewer the experience of peeking into the animal''s world.</td>', 'Oh, that is an unexpected photo!  A really pleasing study of this tortoise (or is it a turtle?)  The very low viewpoint works well, giving the viewer the experience of peeking into the animal''s world.', '2014-04-22 17:33:24.000000', NULL, 1),
(7206867, 1109368, 67258, '<td valign="top">Lovely sense of motion in this one.</td>', 'Lovely sense of motion in this one.', '2014-04-22 17:33:50.000000', NULL, 1),
(7206868, 1108897, 67258, '<td valign="top">A good portrait of this heron, with a pleasingly balanced composition.</td>', 'A good portrait of this heron, with a pleasingly balanced composition.', '2014-04-22 17:34:56.000000', NULL, 1),
(7206871, 1109284, 67258, '<td valign="top">I rather like this - the light is lovely, the composition good, a strong idea of habitat.  I would have scored higher if there were more visible detail in the seal''s face,</td>', 'I rather like this - the light is lovely, the composition good, a strong idea of habitat.  I would have scored higher if there were more visible detail in the seal''s face,', '2014-04-22 17:36:14.000000', NULL, 1),
(7206874, 1108747, 67258, '<td valign="top">A very busy photo  - a shallower depth of field may have helped concentrate the eye on the turkey a little more easily.</td>', 'A very busy photo  - a shallower depth of field may have helped concentrate the eye on the turkey a little more easily.', '2014-04-22 17:37:25.000000', NULL, 1),
(7206877, 1109133, 67258, '<td valign="top">I find it hard to believe that this is a photograph in the generally accepted usage of the term ''wildlife photography''.  It is a good photograph, but I am unconvinced this in the wild.  Just in case I am wrong, I am not going to vote.<br/> <br/>Edit. To make my voting consistent I am going to vote, but adjust downwards for a photo of a captive animal - if I am wrong, my apologies.</td>', 'I find it hard to believe that this is a photograph in the generally accepted usage of the term ''wildlife photography''.  It is a good photograph, but I am unconvinced this in the wild.  Just in case I am wrong, I am not going to vote. Edit. To make my voting consistent I am going to vote, but adjust downwards for a photo of a captive animal - if I am wrong, my apologies.', '2014-04-22 17:41:12.000000', NULL, 1),
(7206881, 1108909, 52854, '<td valign="top">Such a soft and serene photograph - Nice.</td>', 'Such a soft and serene photograph - Nice.', '2014-04-22 17:58:30.000000', NULL, 1),
(7206882, 1109117, 67258, '<td valign="top">The chick is cute, and the exposure against the blue sky reasonable, but the photo is lacking in sharpness, clarity and detail.</td>', 'The chick is cute, and the exposure against the blue sky reasonable, but the photo is lacking in sharpness, clarity and detail.', '2014-04-22 17:59:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7206883, 1109062, 52854, '<td valign="top">I like the bird - but for me, the bottom right corner detracts from the overall photograph.</td>', 'I like the bird - but for me, the bottom right corner detracts from the overall photograph.', '2014-04-22 18:02:26.000000', NULL, 1),
(7206884, 1109470, 52854, '<td valign="top">Wow - Cool shot!</td>', 'Wow - Cool shot!', '2014-04-22 18:03:33.000000', NULL, 1),
(7206885, 1108883, 52854, '<td valign="top">beautiful fox - and photo!</td>', 'beautiful fox - and photo!', '2014-04-22 18:04:03.000000', NULL, 1),
(7206886, 1109388, 52854, '<td valign="top">Well that sure is wild :)</td>', 'Well that sure is wild :)', '2014-04-22 18:05:10.000000', NULL, 1),
(7206887, 1109368, 52854, '<td valign="top">Really Nice Shot! Love the color - Great legs!</td>', 'Really Nice Shot! Love the color - Great legs!', '2014-04-22 18:06:43.000000', NULL, 1),
(7206888, 1109207, 52854, '<td valign="top">Beautiful color - What a gorgeous Bird &amp; Photo!</td>', 'Beautiful color - What a gorgeous Bird & Photo!', '2014-04-22 18:09:25.000000', NULL, 1),
(7206889, 1109340, 52854, '<td valign="top">Really like the photo! What a great face.</td>', 'Really like the photo! What a great face.', '2014-04-22 18:10:38.000000', NULL, 1),
(7206890, 1108897, 52854, '<td valign="top">WoW - Gorgeous Photograph!</td>', 'WoW - Gorgeous Photograph!', '2014-04-22 18:11:45.000000', NULL, 1),
(7206891, 1109244, 52854, '<td valign="top">Beautiful photo!</td>', 'Beautiful photo!', '2014-04-22 18:16:22.000000', NULL, 1),
(7206893, 1109443, 52854, '<td valign="top">A very cool photograph  - Great color - Love the sharpness of the tree and nest -</td>', 'A very cool photograph  - Great color - Love the sharpness of the tree and nest -', '2014-04-22 18:21:23.000000', NULL, 1),
(7206895, 1109059, 52854, '<td valign="top">Nice! - What a beauty! Awesome talons!</td>', 'Nice! - What a beauty! Awesome talons!', '2014-04-22 18:23:02.000000', NULL, 1),
