INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7207859, 1108895, 108580, '<td valign="top">Semantics, I''ve sent you a lengthy PM. Suffices to say what do you call life in the wild then?<br/> <br/></td>', 'Semantics, I''ve sent you a lengthy PM. Suffices to say what do you call life in the wild then? ', '2014-04-24 11:28:52.000000', NULL, 0),
(7207866, 1108895, 108580, '<td valign="top">For a bit of obscure but thought provoking "<strike>humour</strike>" social commentary. I especially like "<a href="//coreybradshaw.files.wordpress.com/2012/12/fence.jpg?w=510" rel="nofollow" target="_blank">The Fence</a>" which refers to the term WILDLIFE in a succint way.<br/><a href="//conservationbytes.com/2014/04/04/cartoon-guide-to-biodiversity-loss-xxiii/" rel="nofollow" target="_blank">//conservationbytes.com/2014/04/04/cartoon-guide-to-biodiversity-loss-xxiii/</a></td>', 'For a bit of obscure but thought provoking "humour" social commentary. I especially like "The Fence" which refers to the term WILDLIFE in a succint way.//conservationbytes.com/2014/04/04/cartoon-guide-to-biodiversity-loss-xxiii/', '2014-04-24 11:41:58.000000', NULL, 0),
(7207870, 1109135, 30861, '<td valign="top">I love the story. It''s a remarkable find and an affecting image. Not enough "subject" for DPC: the single-bluebird shot would have done way better. But you''ve showed us something none of us have seen and few have heard of, so kudos to you :-) <br/> <br/>Unrelated subject: I''m sure you''ve heard of Utah''s "Pando", the massive organism of Aspen shoots? I just read about it and I was stunned...</td>', 'I love the story. It''s a remarkable find and an affecting image. Not enough "subject" for DPC: the single-bluebird shot would have done way better. But you''ve showed us something none of us have seen and few have heard of, so kudos to you :-)  Unrelated subject: I''m sure you''ve heard of Utah''s "Pando", the massive organism of Aspen shoots? I just read about it and I was stunned...', '2014-04-24 11:49:47.000000', NULL, 0),
(7207935, 1108895, 142425, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by HarveyG:</b></div><hr/><i> Semantics, I''ve sent you a lengthy PM. Suffices to say what do you call life in the wild then? </i></td></tr></table> <br/>Hmm...semantics are the stuff of meaning and reality without which we may slip into a world of fantasy. Your PM (yes it <i>was</i> lengthy, wasn''t it?) does not convince me that major wildlife photography competitions do not allow or in specific categories wholeheartedly embrace the hand of Man, and you''ll forgive me if I prefer to go with the establishment on this matter. The definition of wildlife to me is the whole of the animal kingdom, an animal kingdom that includes insects; this challenge did not specifically <i>exclude</i> insects and as far as I am concerned it is up to the voters to make their own informed choice.<br/> <br/>Anyway, DPchallenge is just a bit of fun so let''s agree to differ and lighten up and enjoy our hobby. Have a nice weekend.<br/><br/><i>Message edited by author 2014-04-24 14:39:55.</i></td>', 'Originally posted by HarveyG: Semantics, I''ve sent you a lengthy PM. Suffices to say what do you call life in the wild then?  Hmm...semantics are the stuff of meaning and reality without which we may slip into a world of fantasy. Your PM (yes it was lengthy, wasn''t it?) does not convince me that major wildlife photography competitions do not allow or in specific categories wholeheartedly embrace the hand of Man, and you''ll forgive me if I prefer to go with the establishment on this matter. The definition of wildlife to me is the whole of the animal kingdom, an animal kingdom that includes insects; this challenge did not specifically exclude insects and as far as I am concerned it is up to the voters to make their own informed choice. Anyway, DPchallenge is just a bit of fun so let''s agree to differ and lighten up and enjoy our hobby. Have a nice weekend.', '2014-04-24 15:14:10.000000', '2014-04-24 15:39:55.000000', 0),
